{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C56", "C58", "C48", "C49", "C36", "C44", "C08", "C05", "C10", "C13"],
  "contradictory_card_ids": ["C50", "C21"],
  "prediction_basis_card_ids": ["C56", "C58", "C48", "C49", "C36", "C44", "C08"],
  "claims": [
    {
      "claim": "Lisinopril, the closest structural analog sharing the query's lysine side chain and diacid ACE-inhibitor scaffold, has low predicted passive diffusion but significantly higher in vivo human jejunal effective permeability via hPepT1, supporting carrier-mediated absorption for the query.",
      "card_ids": ["C56"]
    },
    {
      "claim": "Cephalexin and bestatin are confirmed PEPT1 substrates, showing that peptide-like zwitterions with aromatic groups are transported by the intestinal peptide transporter.",
      "card_ids": ["C58", "C48"]
    },
    {
      "claim": "Enalapril shows higher apical-to-basolateral permeability in hiPSC-derived intestinal epithelial layers than in Caco-2 monolayers, indicating that Caco-2 can underestimate intestinal permeability for ACE-inhibitor-like drugs.",
      "card_ids": ["C49"]
    },
    {
      "claim": "Benazepril, which shares the benzazepinone N-acetic acid ring with the query, and lisinopril were highly soluble and did not precipitate in intrinsic solubility determinations.",
      "card_ids": ["C36", "C44"]
    },
    {
      "claim": "Ampicillin, a zwitterionic amino-acid-like drug, had oral bioavailability of 29% in fasted female subjects and 28-54% in cirrhotic patients, all above the 20% threshold.",
      "card_ids": ["C08", "C05", "C10", "C13"]
    },
    {
      "claim": "Enalaprilat's low human jejunal permeability does not transfer to the query because it lacks the lysine primary amine that is the key PEPT1 recognition element.",
      "card_ids": ["C50"]
    },
    {
      "claim": "The low ampicillin oral bioavailability of 12% in fasted veal calves is species-mismatched and does not override the human ampicillin data.",
      "card_ids": ["C21"]
    },
    {
      "claim": "The L6 hepatic-clearance records concern unrelated molecules such as imipramine, nateglinide, thiolactone, and compound 8b, and provide no transferable evidence of high first-pass extraction for the query.",
      "card_ids": ["C60", "C61", "C62", "C67", "C69", "C70", "C71"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C60", "C61", "C62", "C63", "C64", "C65", "C66", "C67", "C68", "C69", "C70", "C71"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "No direct PEPT1 or efflux assay on the query itself is supplied; carrier-mediated absorption is inferred from lisinopril, cephalexin, and bestatin.",
    "No direct hepatic clearance or metabolic-stability measurement exists for the query; L6 records concern other molecules.",
    "Query prandial state and disease condition are unspecified.",
    "First-pass hepatic extraction and systemic clearance are not directly quantified.",
    "The extreme logD of -8.18 remains a physicochemical prior, not affirmative endpoint evidence for F below 20%."
  ],
  "decision_summary": "L6 hepatic-clearance/metabolic-stability records are not applicable to the query and do not provide affirmative evidence of high first-pass extraction; the high prediction based on PEPT1-mediated absorption and solubility is retained."
}

